        ("/// Signalled whenever a worker has made a pipeline.\nstatic DONE: (Mutex<()>, Condvar) = (Mutex::new(()), Condvar::new());",
         "// Optional bounded notification stripes. Live Pending addresses are stable\n// for the duration of every wait/make. Collisions only cause a spurious\n// wakeup: each waiter still checks its own OnceLock predicate.\ntype Completion = (Mutex<()>, Condvar);\n\nstruct CompletionStripes {\n    global: Completion,\n    stripes: [Completion; 64],\n}\n\nimpl CompletionStripes {\n    const fn new() -> Self {\n        Self {\n            global: (Mutex::new(()), Condvar::new()),\n            stripes: [const { (Mutex::new(()), Condvar::new()) }; 64],\n        }\n    }\n    fn index(address: usize) -> usize {\n        let mixed = (address >> 4) ^ (address >> 10) ^ (address >> 16);\n        mixed & 63\n    }\n    fn select(&self, address: usize, striped: bool) -> &Completion {\n        if striped { &self.stripes[Self::index(address)] } else { &self.global }\n    }\n}\n\nstatic COMPLETIONS: CompletionStripes = CompletionStripes::new();\n\nfn completion_stripes_enabled(raw: Option<&str>) -> bool { raw == Some(\"1\") }\n\nfn completion(p: &Pending) -> &'static Completion {\n    static STRIPED: OnceLock<bool> = OnceLock::new();\n    let striped = *STRIPED.get_or_init(|| completion_stripes_enabled(\n        std::env::var(\"VICTORY_PIPELINE_COMPLETION_STRIPES\").ok().as_deref()));\n    COMPLETIONS.select(std::ptr::from_ref(p) as usize, striped)\n}\n\nfn notify_completion(pair: &Completion) {\n    let (lock, done) = pair;\n    let _held = lock.lock().unwrap_or_else(|e| e.into_inner());\n    done.notify_all();\n}\n\nfn wait_completion(pair: &Completion, started: Instant, left: Duration, ready: impl Fn() -> bool) {\n    let (lock, done) = pair;\n    let mut held = lock.lock().unwrap_or_else(|e| e.into_inner());\n    while !ready() {\n        let rest = left.saturating_sub(started.elapsed());\n        if rest.is_zero() { break; }\n        held = done.wait_timeout(held, rest).unwrap_or_else(|e| e.into_inner()).0;\n    }\n}\n\n#[cfg(test)]\nmod completion_stripes_tests {\n    use super::*;\n    #[test]\n    fn explicit_opt_in_and_fixed_routing() {\n        assert!(completion_stripes_enabled(Some(\"1\")));\n        for value in [None, Some(\"\"), Some(\"0\"), Some(\"true\"), Some(\" 1\")] {\n            assert!(!completion_stripes_enabled(value));\n        }\n        let s = CompletionStripes::new();\n        assert!(std::ptr::eq(s.select(0,false), s.select(16,false)));\n        assert!(!std::ptr::eq(s.select(0,true), s.select(16,true)));\n        assert!(std::ptr::eq(s.select(16,true), s.select(16,true)));\n    }\n\n    #[test]\n    fn completion_before_wait_observes_published_result() {\n        let s = CompletionStripes::new();\n        let pair = s.select(16,true);\n        let made = OnceLock::new();\n        made.set(7).unwrap();\n        notify_completion(pair);\n        wait_completion(pair,Instant::now(),Duration::ZERO,|| made.get().is_some());\n        assert_eq!(made.get(),Some(&7));\n    }\n\n    #[test]\n    fn waiter_and_publisher_use_same_lock_without_lost_wakeup() {\n        for striped in [false,true] {\n            let s = CompletionStripes::new();\n            let pair = s.select(16,striped);\n            let made = OnceLock::new();\n            let entered = AtomicBool::new(false);\n            std::thread::scope(|scope| {\n                scope.spawn(|| {\n                    wait_completion(pair, Instant::now(), Duration::from_secs(2), || {\n                        entered.store(true,Ordering::Release);\n                        made.get().is_some()\n                    });\n                    assert_eq!(made.get(),Some(&7));\n                });\n                while !entered.load(Ordering::Acquire) { std::thread::yield_now(); }\n                made.set(7).unwrap();\n                notify_completion(pair);\n            });\n        }\n    }\n\n    #[test]\n    fn colliding_jobs_do_not_satisfy_each_others_predicates() {\n        let s = CompletionStripes::new();\n        let a = 16;\n        let b = (32..65536).step_by(16).find(|&b| CompletionStripes::index(b)==CompletionStripes::index(a)).unwrap();\n        let pair = s.select(a,true);\n        assert!(std::ptr::eq(pair,s.select(b,true)));\n        let made = OnceLock::new();\n        let entered = AtomicBool::new(false);\n        let checks = std::sync::atomic::AtomicUsize::new(0);\n        std::thread::scope(|scope| {\n            scope.spawn(|| {\n                wait_completion(pair,Instant::now(),Duration::from_secs(2),|| {\n                    checks.fetch_add(1,Ordering::Relaxed);\n                    entered.store(true,Ordering::Release);\n                    made.get().is_some()\n                });\n                assert_eq!(made.get(),Some(&9));\n            });\n            while !entered.load(Ordering::Acquire) { std::thread::yield_now(); }\n            notify_completion(s.select(b,true));\n            // The unrelated notification must not publish our result.\n            assert!(made.get().is_none());\n            made.set(9).unwrap();\n            notify_completion(pair);\n        });\n        assert!(checks.load(Ordering::Relaxed)>=2);\n    }\n\n    #[test]\n    fn exhausted_budget_and_unrelated_notification_do_not_publish() {\n        let s = CompletionStripes::new();\n        let made = OnceLock::<u32>::new();\n        notify_completion(s.select(0,true));\n        wait_completion(s.select(16,true),Instant::now(),Duration::ZERO,|| made.get().is_some());\n        assert!(made.get().is_none());\n        wait_completion(s.select(16,true),Instant::now(),Duration::from_millis(1),|| made.get().is_some());\n        assert!(made.get().is_none());\n    }\n}"),
