        ("/// The pipeline named `name`: loaded from the library by `load` if it is",
         "// Optional process-local build gates. These are separate from same_name\n// and one_call. Acquire before either, never while holding saving.\n// Bounded stripes can serialize unrelated names; no pipeline objects,\n// negative results or per-name allocation are retained.\nstruct PipelineBuildGates {\n    locks: [Mutex<()>; 256],\n}\nimpl PipelineBuildGates {\n    const fn new() -> Self { Self { locks: [const { Mutex::new(()) }; 256] } }\n    fn index(name: &str) -> usize {\n        // Mix the entire name rather than just its prefix.\n        name.bytes().fold(0usize, |h,b| h.wrapping_mul(31).wrapping_add(usize::from(b))) % 256\n    }\n    fn enter(&self, name: &str, enabled: bool) -> Option<MutexGuard<'_, ()>> {\n        enabled.then(|| self.locks[Self::index(name)].lock().unwrap_or_else(|e| e.into_inner()))\n    }\n}\n\nfn pipeline_build_gate_enabled(value: Option<&str>) -> bool { value == Some(\"1\") }\n\nfn pipeline_build_gate(name: &str) -> Option<MutexGuard<'static, ()>> {\n    static ENABLED: OnceLock<bool> = OnceLock::new();\n    static GATES: PipelineBuildGates = PipelineBuildGates::new();\n    let enabled = *ENABLED.get_or_init(|| pipeline_build_gate_enabled(\n        std::env::var(\"VICTORY_PIPELINE_BUILD_GATE\").ok().as_deref()));\n    GATES.enter(name, enabled)\n}\n\n#[cfg(test)]\nmod pipeline_build_gate_tests {\n    use super::*;\n    use std::sync::atomic::{AtomicUsize, Ordering};\n    use std::sync::Barrier;\n\n    #[test]\n    fn build_gate_explicit_opt_in_and_disabled_does_not_lock() {\n        assert!(pipeline_build_gate_enabled(Some(\"1\")));\n        for value in [None, Some(\"\"), Some(\"0\"), Some(\"true\"), Some(\" 1\")] {\n            assert!(!pipeline_build_gate_enabled(value));\n        }\n        let gates = PipelineBuildGates::new();\n        let _hold = gates.enter(\"same\", true).unwrap();\n        assert!(gates.enter(\"same\", false).is_none());\n    }\n\n    #[test]\n    fn duplicate_misses_recheck_after_successful_store() {\n        let gates = PipelineBuildGates::new();\n        let stored = std::sync::atomic::AtomicBool::new(false);\n        let compiles = AtomicUsize::new(0);\n        let start = Barrier::new(12);\n        std::thread::scope(|s| {\n            for _ in 0..12 {\n                s.spawn(|| {\n                    start.wait();\n                    let _gate = gates.enter(\"same\", true);\n                    // Synthetic driver-validated Load and Store, not a PSO.\n                    if !stored.load(Ordering::Relaxed) {\n                        compiles.fetch_add(1, Ordering::Relaxed);\n                        stored.store(true, Ordering::Relaxed);\n                    }\n                });\n            }\n        });\n        assert_eq!(compiles.load(Ordering::Relaxed), 1);\n    }\n\n    #[test]\n    fn separate_stripes_progress_while_one_is_held() {\n        let gates = PipelineBuildGates::new();\n        let a = PipelineBuildGates::index(\"a\");\n        let b = PipelineBuildGates::index(\"b\");\n        assert_ne!(a,b);\n        let _hold = gates.enter(\"a\",true);\n        assert!(gates.locks[a].try_lock().is_err());\n        assert!(gates.locks[b].try_lock().is_ok());\n        assert!(gates.enter(\"b\",true).is_some());\n    }\n\n    #[test]\n    fn failed_store_or_compile_is_not_cached_by_gate() {\n        let gates = PipelineBuildGates::new();\n        let mut attempts = 0;\n        let mut cached = false;\n        // Failed compilation, successful creation with failed publication,\n        // then successful creation+publication, then validated cache hit.\n        for attempt in 0..4 {\n            let _gate = gates.enter(\"retry\", true);\n            if !cached {\n                attempts += 1;\n                if attempt == 2 { cached = true; }\n            }\n        }\n        assert_eq!(attempts,3);\n        assert!(cached);\n    }\n\n    #[test]\n    fn unwind_releases_gate_and_poison_does_not_permanently_block() {\n        let gates = PipelineBuildGates::new();\n        assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {\n            let _gate = gates.enter(\"same\",true);\n            panic!(\"simulated compile unwind\");\n        })).is_err());\n        assert!(gates.enter(\"same\",true).is_some());\n    }\n}\n\n/// The pipeline named `name`: loaded from the library by `load` if it is"),
        ("    let began = std::time::Instant::now();\n    let loaded = {\n        let _call = call(\"load from cache (including lock wait)\", name);",
         "    let began = std::time::Instant::now();\n    // Serialize the optional complete load/compile/store sequence, not\n    // just the load. A follower still uses its own descriptor and the\n    // driver's Load validation, and retries creation normally on a miss.\n    let _build = pipeline_build_gate(name);\n    let loaded = {\n        let _call = call(\"load from cache (including lock wait)\", name);"),
