        ("    let mut h = blake3::Hasher::new();\n    h.update(b\"victory shader cache key 2\\0\");\n    if let Some(exe) = exe {\n        h.update(exe);\n    }\n    h.update(&victory_shader::emit::translation_fingerprint());\n    h.update(include_bytes!(\"shader_cache.rs\"));\n    *h.finalize().as_bytes()\n}",
         "    let fingerprint = victory_shader::emit::translation_fingerprint();\n    if build_memo_enabled() {\n        if let Ok(Some(key)) = BUILD_MEMO.try_with(|memo| {\n            memo.try_borrow_mut().ok().map(|mut memo| {\n                memo.get_or_hash(*exe, &fingerprint, || hash_build(*exe, &fingerprint))\n            })\n        }) {\n            return key;\n        }\n    }\n    hash_build(*exe, &fingerprint)\n}\n\n// Re-read every dynamic input above; only the final digest is memoized.\nfn hash_build(exe: Option<[u8; 32]>, fingerprint: &[u8]) -> [u8; 32] {\n    let mut h = blake3::Hasher::new();\n    h.update(b\"victory shader cache key 2\\0\");\n    if let Some(exe) = exe {\n        h.update(&exe);\n    }\n    h.update(fingerprint);\n    h.update(include_bytes!(\"shader_cache.rs\"));\n    *h.finalize().as_bytes()\n}\n\nconst BUILD_MEMO_MAX: usize = 16 * 1024;\n\n#[derive(Default)]\nstruct BuildFingerprintMemo {\n    last: Option<(Option<[u8; 32]>, Vec<u8>, [u8; 32])>,\n}\n\nimpl BuildFingerprintMemo {\n    fn get_or_hash(&mut self, exe: Option<[u8; 32]>, fingerprint: &[u8],\n                   hash: impl FnOnce() -> [u8; 32]) -> [u8; 32] {\n        if let Some((saved_exe, saved, key)) = &self.last {\n            if *saved_exe == exe && saved.as_slice() == fingerprint {\n                return *key;\n            }\n        }\n        let key = hash();\n        self.last = if fingerprint.len() <= BUILD_MEMO_MAX {\n            Some((exe, fingerprint.to_vec(), key))\n        } else {\n            None\n        };\n        key\n    }\n}\n\nthread_local! {\n    static BUILD_MEMO: std::cell::RefCell<BuildFingerprintMemo> =\n        const { std::cell::RefCell::new(BuildFingerprintMemo { last: None }) };\n}\n\nfn build_memo_enabled() -> bool {\n    static ON: OnceLock<bool> = OnceLock::new();\n    *ON.get_or_init(|| std::env::var_os(\"VICTORY_SHADER_BUILD_MEMO\").is_some_and(|v| v == \"1\"))\n}\n\n#[cfg(test)]\nmod build_memo_tests {\n    use super::*;\n\n    #[test]\n    fn exact_hash_and_dynamic_input_invalidation() {\n        let mut memo = BuildFingerprintMemo::default();\n        for (exe, fingerprint) in [\n            (None, &b\"wave32 heap64\"[..]),\n            (None, &b\"wave64 heap64\"[..]),\n            (None, &b\"wave64 heap128\"[..]),\n            (Some([7; 32]), &b\"wave64 heap128\"[..]),\n            (Some([8; 32]), &b\"wave64 heap128\"[..]),\n            (None, &b\"wave32 heap64\"[..]),\n        ] {\n            let mut reference = blake3::Hasher::new();\n            reference.update(b\"victory shader cache key 2\\0\");\n            if let Some(exe) = exe { reference.update(&exe); }\n            reference.update(fingerprint);\n            reference.update(include_bytes!(\"shader_cache.rs\"));\n            let expected = *reference.finalize().as_bytes();\n            assert_eq!(memo.get_or_hash(exe, fingerprint, || hash_build(exe, fingerprint)), expected);\n            assert_eq!(memo.get_or_hash(exe, fingerprint, || panic!(\"exact repeat rehashed\")), expected);\n        }\n    }\n\n    #[test]\n    #[ignore = \"fresh process; explicit memo mode; mutates synthetic translator heap limit\"]\n    fn actual_build_memo_modes_and_tls_fallback() {\n        use victory_shader::emit::{set_view_heap_limit, view_heap_limit, translation_fingerprint};\n        let mode = std::env::var(\"VICTORY_SHADER_BUILD_MEMO\").unwrap();\n        assert!(matches!(mode.as_str(), \"0\" | \"1\"));\n        let enabled = mode == \"1\";\n        assert_eq!(build_memo_enabled(), enabled);\n        struct Restore(u32);\n        impl Drop for Restore {\n            fn drop(&mut self) { set_view_heap_limit(self.0); }\n        }\n        let _restore = Restore(view_heap_limit());\n        let exe = if std::env::var_os(\"VICTORY_SHADER_CACHE_KEY\").is_some_and(|v| v == \"exe\") {\n            Some(*blake3::hash(&std::fs::read(std::env::current_exe().unwrap()).unwrap()).as_bytes())\n        } else {\n            None\n        };\n        let reference = || {\n            let fingerprint = translation_fingerprint();\n            assert!(fingerprint.len() <= BUILD_MEMO_MAX);\n            let mut h = blake3::Hasher::new();\n            h.update(b\"victory shader cache key 2\\0\");\n            if let Some(exe) = exe { h.update(&exe); }\n            h.update(&fingerprint);\n            h.update(include_bytes!(\"shader_cache.rs\"));\n            *h.finalize().as_bytes()\n        };\n        BUILD_MEMO.with(|m| assert!(m.borrow().last.is_none()));\n        set_view_heap_limit(64);\n        let a = build();\n        assert_eq!(a, reference());\n        assert_eq!(build(), a);\n        BUILD_MEMO.with(|m| assert_eq!(m.borrow().last.is_some(), enabled));\n\n        // A borrow conflict must bypass the memo, not panic or return a\n        // stale key. The borrowed entry must remain exactly as it was.\n        BUILD_MEMO.with(|m| {\n            let held = m.borrow_mut();\n            let previous = held.last.clone();\n            set_view_heap_limit(128);\n            let b = build();\n            assert_eq!(b, reference());\n            assert_ne!(a, b);\n            assert_eq!(held.last, previous);\n        });\n        let b = build();\n        assert_eq!(b, reference());\n        assert_ne!(a, b);\n        BUILD_MEMO.with(|m| {\n            let memo = m.borrow();\n            assert_eq!(memo.last.is_some(), enabled);\n            if let Some((_, fingerprint, key)) = &memo.last {\n                assert_eq!(fingerprint, &translation_fingerprint());\n                assert_eq!(*key, b);\n            }\n        });\n\n        // Other threads start with a fresh entry and cannot replace ours.\n        std::thread::scope(|scope| {\n            scope.spawn(|| {\n                BUILD_MEMO.with(|m| assert!(m.borrow().last.is_none()));\n                assert_eq!(build(), b);\n                BUILD_MEMO.with(|m| assert_eq!(m.borrow().last.is_some(), enabled));\n            }).join().unwrap();\n        });\n        assert_eq!(build(), b);\n        set_view_heap_limit(64);\n        assert_eq!(build(), a);\n        assert_eq!(build(), reference());\n    }\n\n    #[test]\n    fn oversized_fingerprint_is_not_retained() {\n        let mut memo = BuildFingerprintMemo::default();\n        let small = vec![1; BUILD_MEMO_MAX];\n        let large = vec![2; BUILD_MEMO_MAX + 1];\n        assert_eq!(memo.get_or_hash(None, &small, || hash_build(None, &small)), hash_build(None, &small));\n        assert!(memo.last.is_some());\n        for _ in 0..2 {\n            assert_eq!(memo.get_or_hash(None, &large, || hash_build(None, &large)), hash_build(None, &large));\n            assert!(memo.last.is_none());\n        }\n    }\n}"),
