        ("struct Translate<F> {\n    translate: F,\n    ran: AtomicBool,\n}\n\nimpl<F: Fn(&[u8]) -> Result<HostShader, String> + Send + Sync> Converter for Translate<F> {\n    fn id(&self) -> &'static str {\n        \"shader.dxil\"\n    }\n    fn version(&self) -> u32 {\n        // The build fingerprint in the input does the versioning.\n        1\n    }\n    fn convert(&self, input: &[u8]) -> anyhow::Result<Vec<u8>> {\n        self.ran.store(true, Ordering::Relaxed);\n        let shader = (self.translate)(&input[32..]).map_err(anyhow::Error::msg)?;\n        Ok(encode(&shader))\n    }\n}\n\nfn cached(\n    cache: &Cache,\n    build: &[u8; 32],\n    container: &[u8],\n    translate: impl Fn(&[u8]) -> Result<HostShader, String> + Send + Sync,\n) -> Result<HostShader, String> {\n    let input = [&build[..], container].concat();\n    let converter = Translate {\n        translate,\n        ran: AtomicBool::new(false),\n    };\n    for _ in 0..2 {\n        let path = cache\n            .get_or_convert(&converter, &input)\n            .map_err(|e| format!(\"{e:#}\"))?;\n        if let Some(shader) = std::fs::read(&path).ok().and_then(|b| decode(&b)) {\n            let (counter, what) = if converter.ran.load(Ordering::Relaxed) {\n                (&MISSES, \"translated and cached\")\n            } else {\n                (&HITS, \"from the cache\")\n            };\n            counter.fetch_add(1, Ordering::Relaxed);\n            tracing::debug!(path = %path.display(), \"shader {what}\");\n            return Ok(shader);\n        }\n        tracing::debug!(path = %path.display(), \"unreadable shader cache entry; translating again\");\n        let _ = std::fs::remove_file(&path);\n    }\n    MISSES.fetch_add(1, Ordering::Relaxed);\n    (converter.translate)(container)\n}\n\n",
         "struct Translate<F> {\n    translate: F,\n    ran: AtomicBool,\n    // Retain a successful translation until the cache has published it.\n    // Disk I/O is optional for gameplay, but not for offline warming.\n    completed: std::sync::Mutex<Option<HostShader>>,\n}\n\nimpl<F: Fn(&[u8]) -> Result<HostShader, String> + Send + Sync> Converter for Translate<F> {\n    fn id(&self) -> &'static str {\n        \"shader.dxil\"\n    }\n    fn version(&self) -> u32 {\n        // The build fingerprint in the input does the versioning.\n        1\n    }\n    fn convert(&self, input: &[u8]) -> anyhow::Result<Vec<u8>> {\n        self.ran.store(true, Ordering::Relaxed);\n        let mut completed = self.completed.lock().unwrap_or_else(|e| e.into_inner());\n        *completed = None;\n        let shader = (self.translate)(&input[32..]).map_err(anyhow::Error::msg)?;\n        let bytes = encode(&shader);\n        *completed = Some(shader);\n        Ok(bytes)\n    }\n}\n\nfn cached(\n    cache: &Cache,\n    build: &[u8; 32],\n    container: &[u8],\n    translate: impl Fn(&[u8]) -> Result<HostShader, String> + Send + Sync,\n) -> Result<HostShader, String> {\n    cached_with_policy(cache, build, container, translate, true)\n}\n\nfn reuse_translated(raw: Option<&str>) -> bool { raw == Some(\"1\") }\n\nfn reuse_translated_on() -> bool {\n    static ON: OnceLock<bool> = OnceLock::new();\n    *ON.get_or_init(|| reuse_translated(std::env::var(\"VICTORY_SHADER_CACHE_REUSE_TRANSLATED\").ok().as_deref()))\n}\n\nfn cached_with_policy(\n    cache: &Cache,\n    build: &[u8; 32],\n    container: &[u8],\n    translate: impl Fn(&[u8]) -> Result<HostShader, String> + Send + Sync,\n    allow_uncached: bool,\n) -> Result<HostShader, String> {\n    let input = [&build[..], container].concat();\n    let converter = Translate {\n        translate,\n        ran: AtomicBool::new(false),\n        completed: std::sync::Mutex::new(None),\n    };\n    for _ in 0..2 {\n        let path = match cache.get_or_convert(&converter, &input) {\n            Ok(path) => path,\n            Err(e) => {\n                // A conversion failure has no completed shader. A publication\n                // failure after conversion must not permanently disable a\n                // valid shader for this gameplay session.\n                if allow_uncached {\n                    let completed = converter.completed.lock()\n                        .unwrap_or_else(|e| e.into_inner()).take();\n                    if let Some(shader) = completed {\n                        MISSES.fetch_add(1, Ordering::Relaxed);\n                        tracing::warn!(error = %e, \"shader cache publication failed; using uncached translation\");\n                        return Ok(shader);\n                    }\n                }\n                return Err(format!(\"{e:#}\"));\n            }\n        };\n        // Only this invocation's successful conversion is eligible. A hit\n        // must still decode its bytes; offline warming must verify disk.\n        if allow_uncached && reuse_translated_on() {\n            let completed = converter.completed.lock()\n                .unwrap_or_else(|e| e.into_inner()).take();\n            if let Some(shader) = completed {\n                MISSES.fetch_add(1, Ordering::Relaxed);\n                tracing::debug!(path = %path.display(), \"shader translated and cached; reused translation\");\n                return Ok(shader);\n            }\n        }\n        if let Some(shader) = std::fs::read(&path).ok().and_then(|b| decode(&b)) {\n            let (counter, what) = if converter.ran.load(Ordering::Relaxed) {\n                (&MISSES, \"translated and cached\")\n            } else {\n                (&HITS, \"from the cache\")\n            };\n            counter.fetch_add(1, Ordering::Relaxed);\n            tracing::debug!(path = %path.display(), \"shader {what}\");\n            return Ok(shader);\n        }\n        // If this call just translated successfully, use that result for\n        // gameplay rather than translating a second time. The broken\n        // entry is still removed so another process can rebuild it.\n        tracing::debug!(path = %path.display(), \"unreadable shader cache entry; translating again\");\n        let _ = std::fs::remove_file(&path);\n        if allow_uncached {\n            let completed = converter.completed.lock()\n                .unwrap_or_else(|e| e.into_inner()).take();\n            if let Some(shader) = completed {\n                MISSES.fetch_add(1, Ordering::Relaxed);\n                return Ok(shader);\n            }\n        }\n    }\n    if !allow_uncached {\n        return Err(\"shader cache entry could not be read after two attempts\".to_owned());\n    }\n    MISSES.fetch_add(1, Ordering::Relaxed);\n    (converter.translate)(container)\n}\n\n"),
        ("    #[test]\n    fn entries_round_trip_and_reject_damage() {",
         "    #[test]\n    #[ignore = \"isolated shader cache reuse mode; explicit env 0 or 1\"]\n    fn shader_cache_reuse_actual_equivalence() {\n        let mode = std::env::var(\"VICTORY_SHADER_CACHE_REUSE_TRANSLATED\").unwrap();\n        assert!(matches!(mode.as_str(), \"0\" | \"1\"));\n        assert_eq!(reuse_translated_on(), mode == \"1\");\n        for stage in STAGES {\n            let dir = tempfile::tempdir().unwrap();\n            let cache = Cache::open(dir.path()).unwrap();\n            let build = [13u8; 32];\n            let container = b\"synthetic shader reuse fixture\";\n            let mut expected = shader();\n            expected.stage = stage;\n            let encoded = encode(&expected);\n            let runs = AtomicU64::new(0);\n            let translate = |_: &[u8]| {\n                runs.fetch_add(1, Ordering::Relaxed);\n                Ok(expected.clone())\n            };\n            let cold = cached(&cache, &build, container, translate).unwrap();\n            assert_eq!(cold, expected);\n            assert_eq!(encode(&cold), encoded);\n            let files = walk(dir.path());\n            assert_eq!(files.len(), 1);\n            assert_eq!(std::fs::read(&files[0]).unwrap(), encoded);\n            let hit = cached(&cache, &build, container, translate).unwrap();\n            assert_eq!(hit, cold);\n            assert_eq!(runs.load(Ordering::Relaxed), 1);\n            std::fs::write(&files[0], b\"VSH1 damaged\").unwrap();\n            let recovered = cached(&cache, &build, container, translate).unwrap();\n            assert_eq!(recovered, expected);\n            assert_eq!(encode(&recovered), encoded);\n            assert_eq!(std::fs::read(&files[0]).unwrap(), encoded);\n            assert_eq!(runs.load(Ordering::Relaxed), 2);\n            // A different key forces strict offline-style cold publication.\n            let strict = cached_with_policy(&cache, &[14u8; 32], container, translate, false).unwrap();\n            assert_eq!(strict, expected);\n            assert_eq!(encode(&strict), encoded);\n            assert_eq!(runs.load(Ordering::Relaxed), 3);\n            let files = walk(dir.path());\n            assert_eq!(files.len(), 2);\n            for file in files {\n                assert_eq!(decode(&std::fs::read(file).unwrap()), Some(expected.clone()));\n            }\n        }\n    }\n\n    // Measure real cache publication/readback with synthetic HostShader\n    // data only. Use a separate fresh process for each explicit mode.\n    #[test]\n    #[ignore = \"bounded release-mode shader cache measurement\"]\n    fn shader_cache_reuse_measurement() {\n        use std::time::Instant;\n        let mode = std::env::var(\"VICTORY_SHADER_CACHE_REUSE_TRANSLATED\").unwrap();\n        assert!(matches!(mode.as_str(), \"0\" | \"1\"));\n        assert_eq!(reuse_translated_on(), mode == \"1\");\n        const N: usize = 16;\n        for bytes in [4096usize, 65536, 262144] {\n            let mut expected = shader();\n            expected.dxil = (0..bytes).map(|i| (i % 251) as u8).collect();\n            let encoded = encode(&expected);\n            for repeat in 0..4 {\n                let dir = tempfile::tempdir().unwrap();\n                let cache = Cache::open(dir.path()).unwrap();\n                let build = [19u8; 32];\n                let keys: Vec<_> = (0..N).map(|i| (i as u32).to_le_bytes()).collect();\n                let runs = AtomicU64::new(0);\n                let translate = |_: &[u8]| {\n                    runs.fetch_add(1, Ordering::Relaxed);\n                    Ok(expected.clone())\n                };\n                let mut cold = Vec::with_capacity(N);\n                let start = Instant::now();\n                for key in &keys {\n                    cold.push(cached(&cache, &build, key, translate).unwrap());\n                }\n                let cold_ns = start.elapsed().as_nanos();\n                assert_eq!(runs.load(Ordering::Relaxed), N as u64);\n                assert!(cold.iter().all(|value| value == &expected));\n                drop(cold);\n                let mut warm = Vec::with_capacity(N);\n                let start = Instant::now();\n                for key in &keys {\n                    warm.push(cached(&cache, &build, key, translate).unwrap());\n                }\n                let warm_ns = start.elapsed().as_nanos();\n                assert_eq!(runs.load(Ordering::Relaxed), N as u64);\n                assert!(warm.iter().all(|value| value == &expected));\n                let files = walk(dir.path());\n                assert_eq!(files.len(), N);\n                for file in files {\n                    assert_eq!(std::fs::read(file).unwrap(), encoded);\n                }\n                // Exclude the first batch from the receipt, not validation.\n                if repeat != 0 {\n                    println!(\"shader_cache_reuse mode={} bytes={} repeat={} keys={} cold_ns={} warm_ns={}\",\n                        mode, bytes, repeat, N, cold_ns, warm_ns);\n                }\n            }\n        }\n    }\n\n    #[test]\n    fn shader_cache_publication_failure_keeps_runtime_translation() {\n        let dir = tempfile::tempdir().unwrap();\n        let cache = Cache::open(dir.path()).unwrap();\n        let build = [9u8; 32];\n        let container = b\"synthetic shader\";\n        let runs = AtomicU64::new(0);\n        let translate = |_: &[u8]| {\n            runs.fetch_add(1, Ordering::Relaxed);\n            Ok(shader())\n        };\n        let converter = Translate {\n            translate,\n            ran: AtomicBool::new(false),\n            completed: std::sync::Mutex::new(None),\n        };\n        let input = [&build[..], &container[..]].concat();\n        let path = cache.path_for(&victory_pipeline::CacheKey::new(&converter, &input));\n        // Force the real cache's final rename to fail, after translation.\n        std::fs::create_dir_all(&path).unwrap();\n        assert_eq!(cached(&cache, &build, container, translate), Ok(shader()));\n        assert_eq!(runs.load(Ordering::Relaxed), 1);\n        assert!(path.is_dir());\n        assert!(cached_with_policy(&cache, &build, container, translate, false).is_err());\n        assert_eq!(runs.load(Ordering::Relaxed), 2);\n        let fail = |_: &[u8]| Err::<HostShader, _>(\"unsupported synthetic shader\".to_owned());\n        assert!(cached(&cache, &build, container, fail).unwrap_err().contains(\"unsupported synthetic shader\"));\n        // A later writable cache succeeds and the following lookup hits.\n        std::fs::remove_dir(&path).unwrap();\n        assert_eq!(cached(&cache, &build, container, translate), Ok(shader()));\n        assert_eq!(cached(&cache, &build, container, translate), Ok(shader()));\n        assert_eq!(runs.load(Ordering::Relaxed), 3);\n    }\n\n    #[test]\n    fn entries_round_trip_and_reject_damage() {"),
